func:
flow.set('zelnumBulkQuote',undefined);
 const apiKey=env.get('ZELNUM_API_KEY'), product=String(env.get('ZELNUM_BULK_PRODUCT')||'').trim();
 const series=String(env.get('ZELNUM_BULK_SERIES')||'phone').trim().toLowerCase();
 const identifiers=String(env.get('ZELNUM_IDENTIFIERS')||'').split(/[,\r\n]+/).map(s=>s.trim()).filter(Boolean);
 const catalog=flow.get('zelnumBulkCatalog');
 if(!apiKey||!product||!identifiers.length||!['phone','email'].includes(series)){node.error('Set API key, bulk product slug, phone/email series and your own list of identifiers. No sample list is submitted automatically.',msg);return null;}
 if(!catalog||Date.now()-catalog.fetchedAt>300000){node.error('Click Get products first to load current minimum batch sizes.',msg);return null;}
 const selected=catalog.products.find(p=>p.slug===product&&p.mode==='async'&&p.series===series);
 const minimum=selected&&Number(selected.min_phones);
 if(!selected||!Number.isInteger(minimum)||minimum<1){node.error('Select a current async product matching the series from Get products.',msg);return null;}
 if(identifiers.length<minimum){node.error(`Product ${product} requires at least ${minimum} rows; provided ${identifiers.length}. Do not pad with dummy or repeated data.`,msg);return null;}
 if(identifiers.length>10000){node.error('This array quote example supports at most 10,000 rows. Split larger lists or consult the file submission API.',msg);return null;}
 const body={product,phones:identifiers};
 if(series==='phone')body.country=String(env.get('ZELNUM_COUNTRY')||'US').trim().toUpperCase();
 msg.method='POST';msg.url='https://api.zelnum.com/api/v1/quotes/bulk';
 msg.headers={'X-API-Key':apiKey,'Content-Type':'application/json'};
 msg.payload=body;msg.zelnum={series,body:JSON.parse(JSON.stringify(body))};
 return msg;

delete msg.headers;
if (Number(msg.statusCode) < 200 || Number(msg.statusCode) >= 300 || !msg.payload || !msg.payload.quote || !msg.zelnum) {
  flow.set('zelnumBulkQuote', undefined); node.error('Quote failed: ' + ((msg.payload && (msg.payload.message || msg.payload.code)) || msg.statusCode), msg); return null;
}
const quote = msg.payload.quote;
if (!quote.quote_token || !Number.isFinite(Number(quote.total)) || !Number.isFinite(Date.parse(quote.expires_at)) || Date.parse(quote.expires_at) <= Date.now()) {
  flow.set('zelnumBulkQuote', undefined); node.error('Invalid or expired quote; request a new one.', msg); return null;
}
flow.set('zelnumBulkQuote', {quote, request: msg.zelnum});
msg.payload = {quote, count: msg.zelnum.body.phones.length, next: 'Review the price before clicking the separate BILLABLE inject. Keep the idempotency key for retries; use a new key for each new request.'};
return msg;

const saved = flow.get('zelnumBulkQuote');
const apiKey = env.get('ZELNUM_API_KEY');
const idempotencyKey = String(env.get('ZELNUM_IDEMPOTENCY_KEY') || '').trim();
if (!apiKey || !idempotencyKey) { node.error('Set API key and a unique idempotency key for this logical request.', msg); return null; }
if (!saved || !saved.request || !saved.quote || Date.parse(saved.quote.expires_at) <= Date.now()) { node.error('Get a fresh quote first; quotes expire.', msg); return null; }
const series = String(env.get('ZELNUM_BULK_SERIES') || 'phone').trim().toLowerCase();
const current = {product: String(env.get('ZELNUM_BULK_PRODUCT') || '').trim(), phones: String(env.get('ZELNUM_IDENTIFIERS') || '').split(/[,\r\n]+/).map(s => s.trim()).filter(Boolean)};
if (series === 'phone') current.country = String(env.get('ZELNUM_COUNTRY') || 'US').trim().toUpperCase();
if (series !== saved.request.series || JSON.stringify(current) !== JSON.stringify(saved.request.body)) { node.error('Inputs changed after quoting (including country). Get a new quote and review its price.', msg); return null; }
if (saved.idempotencyKey && saved.idempotencyKey !== idempotencyKey) { node.error('This quote has already been executed. Keep its key for retries or get a new quote for a new request.', msg); return null; }
saved.idempotencyKey = idempotencyKey; flow.set('zelnumBulkQuote', saved);
msg.method = 'POST'; msg.url = 'https://api.zelnum.com/api/v1/detect';
msg.headers = {'X-API-Key': apiKey, 'Content-Type': 'application/json', 'Idempotency-Key': idempotencyKey, 'X-ZelNum-Quote': saved.quote.quote_token, 'X-ZelNum-Quote-Amount': String(saved.quote.total)};
msg.payload = JSON.parse(JSON.stringify(saved.request.body));
return msg;

delete msg.headers;
if (Number(msg.statusCode)!==202 || !msg.payload || !msg.payload.task_id) {node.error('Submission failed: ' + ((msg.payload && (msg.payload.message || msg.payload.code)) || msg.statusCode),msg);return null;}
flow.set('zelnumBulkTaskId',msg.payload.task_id);
flow.set('zelnumBulkStatus',undefined);
return msg;

const apiKey=env.get('ZELNUM_API_KEY');
const taskId=env.get('ZELNUM_TASK_ID') || flow.get('zelnumBulkTaskId');
if(!apiKey || !taskId){node.error('Set API key and submit a task, or set ZELNUM_TASK_ID to resume an existing task.',msg);return null;}
msg.method='GET';msg.url='https://api.zelnum.com/api/v1/tasks/'+encodeURIComponent(taskId);msg.headers={'X-API-Key':apiKey};msg.payload=undefined;return msg;

if(Number(msg.statusCode)!==200 || !msg.payload || !Array.isArray(msg.payload.data)){node.error('Cannot load current products.',msg);return null;}
flow.set('zelnumBulkCatalog',{products:msg.payload.data,fetchedAt:Date.now()});
msg.payload=msg.payload.data.filter(p=>p.mode==='async').map(p=>({slug:p.slug,series:p.series,min_phones:p.min_phones}));
delete msg.headers;return msg;

delete msg.headers;
if(Number(msg.statusCode)!==200 || !msg.payload || !msg.payload.task_id){node.error('Status request failed.',msg);return null;}
flow.set('zelnumBulkStatus',msg.payload);
if(msg.payload.status==='completed' && !msg.payload.result_available){
 msg.payload={...msg.payload,notice:'Task completed, but its result is unavailable or expired. It is not still processing.'};
} else if(msg.payload.status==='failed'){msg.payload={...msg.payload,notice:msg.payload.failure_message || 'Task failed.'};}
return msg;

const apiKey=env.get('ZELNUM_API_KEY');
const taskId=env.get('ZELNUM_TASK_ID') || flow.get('zelnumBulkTaskId');
if(!apiKey || !taskId){node.error('Set API key and a task ID.',msg);return null;}
msg.zelnumTaskId=String(taskId);msg.method='GET';msg.url='https://api.zelnum.com/api/v1/tasks/'+encodeURIComponent(taskId)+'/result';
msg.headers={'X-API-Key':apiKey};msg.payload=undefined;return msg;

delete msg.headers;
if(Number(msg.statusCode)!==200 || !msg.payload || !msg.payload.download_url){
 const body=msg.payload || {};
 const explanation=Number(msg.statusCode)===404?'Result expired, unavailable or not found; do not treat it as still processing.':Number(msg.statusCode)===422?'Result is not ready. Check task status.':(body.message || body.code || 'Result request failed.');
 node.error(explanation,msg);return null;
}
if(msg.payload.expires_at && Date.parse(msg.payload.expires_at)<=Date.now()){node.error('Result expired. It is no longer downloadable.',msg);return null;}
const expected='https://api.zelnum.com/api/v1/tasks/'+encodeURIComponent(msg.zelnumTaskId)+'/download';
if(msg.payload.download_url!==expected){node.error('Unexpected download URL; API key was not forwarded.',msg);return null;}
msg.zelnumResult=msg.payload;
msg.method='GET';msg.url=expected;msg.headers={'X-API-Key':env.get('ZELNUM_API_KEY')};msg.payload=undefined;return msg;

delete msg.headers;
if(Number(msg.statusCode)!==200 || !Buffer.isBuffer(msg.payload) || msg.payload.length===0){node.error('Download failed or was empty; no result file was written.',msg);return null;}
msg.filename=String(msg.zelnumTaskId)+(msg.payload[0]===0x50&&msg.payload[1]===0x4b?'.zip':'.csv');
msg.zelnumDownload={task_id:msg.zelnumTaskId,filename:msg.filename,bytes:msg.payload.length,expires_at:msg.zelnumResult.expires_at};
return msg;
